    # Collapse adjacent identical rows, then adjacent identical columns.
    rows = []
    for row in grid:
        if not rows or row != rows[-1]:
            rows.append(row[:])
    if not rows:
        return []
    out = []
    for c in range(len(rows[0])):
        col = tuple(row[c] for row in rows)
        if not out or col != out[-1]:
